function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'Encrypter' || operations.slice(1).some(op => op !== 'encrypt' && op !== 'decrypt')) return 'Start with Encrypter, then call only encrypt and decrypt.';
  if (operations.length - 1 > 200) return 'At most 200 calls to encrypt and decrypt.';
  const [keys, values, dictionary] = args[0] ?? [];
  const lower = (text, min, max) => typeof text === 'string' && text.length >= min && text.length <= max && /^[a-z]*$/.test(text);
  if (!Array.isArray(keys) || keys.length < 1 || keys.length > 26 || !keys.every(k => lower(k, 1, 1))) return 'keys holds 1 to 26 lowercase letters.';
  if (new Set(keys).size !== keys.length) return 'keys must be distinct.';
  if (!Array.isArray(values) || values.length !== keys.length || !values.every(v => lower(v, 2, 2))) return 'values needs one 2-letter lowercase code per key.';
  if (!Array.isArray(dictionary) || dictionary.length < 1 || dictionary.length > 100 || !dictionary.every(w => lower(w, 1, 100))) return 'dictionary holds 1 to 100 lowercase words of 1 to 100 letters.';
  if (new Set(dictionary).size !== dictionary.length) return 'dictionary words must be distinct.';
  for (let i = 1; i < operations.length; i++) {
    const text = Array.isArray(args[i]) ? args[i][0] : undefined;
    if (operations[i] === 'encrypt') {
      if (!lower(text, 1, 2000)) return 'word1 has 1 to 2000 lowercase letters.';
      if ([...text].some(ch => !keys.includes(ch))) return 'Every letter of word1 must be one of keys.';
    } else if (!lower(text, 2, 200) || text.length % 2 !== 0) return 'word2 has an even length from 2 to 200, lowercase letters only.';
  }
  return null;
}

