class Encrypter {
  constructor(keys, values, dictionary) {
    this.codeOf = new Map();
    for (let i = 0; i < keys.length; i++) {
      this.codeOf.set(keys[i], values[i]);
    }
    this.countOf = new Map();
    for (const word of dictionary) {
      const encrypted = this.encrypt(word);
      if (encrypted === '') {
        continue;
      }
      this.countOf.set(encrypted, (this.countOf.get(encrypted) ?? 0) + 1);
    }
  }

  encrypt(word1) {
    const parts = [];
    for (const ch of word1) {
      const code = this.codeOf.get(ch);
      if (code === undefined) {
        return '';
      }
      parts.push(code);
    }
    return parts.join('');
  }

  decrypt(word2) {
    return this.countOf.get(word2) ?? 0;
  }
}

