class Encrypter {
  constructor(keys, values, dictionary) {
    this.keys = keys.slice();
    this.values = values.slice();
    this.dictionary = dictionary.slice();
  }
  encrypt(word1) {
    let out = '';
    for (let j = 0; j < word1.length; j++) {
      const at = this.keys.indexOf(word1[j]);
      if (at < 0) return '';
      out += this.values[at];
    }
    return out;
  }
  decrypt(word2) {
    // For every block, list the keys it may stand for, then test each dictionary word directly.
    const blocks = [];
    for (let j = 0; j < word2.length; j += 2) {
      const block = word2.slice(j, j + 2);
      blocks.push(this.keys.filter((key, i) => this.values[i] === block));
    }
    let count = 0;
    for (const word of this.dictionary) {
      if (word.length !== blocks.length) continue;
      let fits = true;
      for (let j = 0; j < word.length && fits; j++) if (!blocks[j].includes(word[j])) fits = false;
      if (fits) count++;
    }
    return count;
  }
}

