function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (text) => text[Math.floor(rand() * text.length)];
  const shuffled = letters.split('');
  for (let i = shuffled.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]; }
  const keyCount = large ? 20 + Math.floor(rand() * 7) : 1 + Math.floor(rand() * 5);
  const keys = shuffled.slice(0, keyCount);
  const keyText = keys.join('');
  // A small pool of codes makes several keys share a code, so decrypt has real choices.
  const codeLetters = large ? 'abcdef' : 'xyz';
  const poolSize = large ? 4 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 3);
  const pool = Array.from({ length: poolSize }, () => pick(codeLetters) + pick(codeLetters));
  const values = keys.map(() => pool[Math.floor(rand() * pool.length)]);
  const outside = letters.split('').filter(c => !keys.includes(c)).join('') || 'a';
  const word = (maxLength, allowOutside) => {
    const length = 1 + Math.floor(rand() * maxLength);
    let text = '';
    for (let i = 0; i < length; i++) text += allowOutside && rand() < 0.05 ? pick(outside) : pick(keyText);
    return text;
  };
  const dictSize = large ? 100 : 1 + Math.floor(rand() * 7);
  const seen = new Set();
  for (let tries = 0; seen.size < dictSize && tries < 5000; tries++) {
    const maxLength = large ? (rand() < 0.7 ? 4 : 100) : 3;
    seen.add(word(maxLength, true));
  }
  const dictionary = [...seen];
  const encode = (text) => { let out = ''; for (const ch of text) { const at = keys.indexOf(ch); if (at < 0) return ''; out += values[at]; } return out; };
  const operations = ['Encrypter'];
  const args = [[keys, values, dictionary]];
  const calls = large ? 200 : 1 + Math.floor(rand() * 7);
  for (let c = 0; c < calls; c++) {
    if (rand() < 0.3) {
      operations.push('encrypt');
      args.push([word(large ? (rand() < 0.2 ? 2000 : 100) : 5, false)]);
      continue;
    }
    operations.push('decrypt');
    const choice = rand();
    let target = '';
    if (choice < 0.6) target = encode(dictionary[Math.floor(rand() * dictionary.length)]);
    else if (choice < 0.85) target = encode(word(large ? 100 : 3, false));
    if (target === '') {
      const blocks = 1 + Math.floor(rand() * (large ? 100 : 3));
      for (let b = 0; b < blocks; b++) target += rand() < 0.7 ? pool[Math.floor(rand() * pool.length)] : pick(letters) + pick(letters);
    }
    args.push([target]);
  }
  return [operations, args];
}
